func ReleaseSaveMessageBody(w *TableMessageWriter, value *Release) bool {
	{
		if value.Id != 0 {
			w.Put(7, TableMessageRefBitsHere)
			if value.Id == 0 {
				w.Put(0, w.IndexBits)
			} else {
				index, ok := w.Numbering.Index(&value.Id)
				if !ok {
					return false
				}
				w.Put(index, w.IndexBits)
			}
		}
	}
	{
		if value.Status != ReleaseStatusNone {
			w.Put(10, TableMessageRefBitsHere)
			if value.Status == ReleaseStatusNone {
				w.Put(0, TableMessageRefBitsHere)
			} else {
				id, named := value.Status.TableEnumId()
				if !named {
					return false
				}
				slot := tableMessageNameSlot(id)
				if slot == 0 {
					return false
				}
				w.Put(slot, TableMessageRefBitsHere)
			}
		}
	}
	{
		if value.Text != 0 {
			w.Put(2, TableMessageRefBitsHere)
			if value.Text == 0 {
				w.Put(0, w.IndexBits)
			} else {
				index, ok := w.Numbering.Index(&value.Text)
				if !ok {
					return false
				}
				w.Put(index, w.IndexBits)
			}
		}
	}
	{
		if value.DateLength < 0 || value.DateLength > 10 {
			return false
		}
		if value.DateLength > 0 {
			w.Put(15, TableMessageRefBitsHere)
			if value.DateLength < 0 || value.DateLength > 10 {
				return false
			}
			w.Put(uint64(value.DateLength), 4)
			w.Raw(value.Date[:value.DateLength])
		}
	}
	w.Put(0, TableMessageRefBitsHere)
	return !w.Overflow
}
