func FixSaveMessageBody(w *TableMessageWriter, value *Fix) bool {
	{
		if value.Id != 0 {
			w.Put(7, TableMessageRefBitsHere)
			if value.Id == 0 {
				w.Put(0, w.IndexBits)
			} else {
				index, ok := w.Numbering.Index(&value.Id)
				if !ok {
					return false
				}
				w.Put(index, w.IndexBits)
			}
		}
	}
	{
		if value.Release != 0 {
			w.Put(8, TableMessageRefBitsHere)
			if value.Release == 0 {
				w.Put(0, w.IndexBits)
			} else {
				index, ok := w.Numbering.Index(&value.Release)
				if !ok {
					return false
				}
				w.Put(index, w.IndexBits)
			}
		}
	}
	{
		if value.Title != 0 {
			w.Put(1, TableMessageRefBitsHere)
			if value.Title == 0 {
				w.Put(0, w.IndexBits)
			} else {
				index, ok := w.Numbering.Index(&value.Title)
				if !ok {
					return false
				}
				w.Put(index, w.IndexBits)
			}
		}
	}
	{
		if value.Text != 0 {
			w.Put(2, TableMessageRefBitsHere)
			if value.Text == 0 {
				w.Put(0, w.IndexBits)
			} else {
				index, ok := w.Numbering.Index(&value.Text)
				if !ok {
					return false
				}
				w.Put(index, w.IndexBits)
			}
		}
	}
	{
		if value.Origin != 0 {
			w.Put(9, TableMessageRefBitsHere)
			if value.Origin == 0 {
				w.Put(0, w.IndexBits)
			} else {
				index, ok := w.Numbering.Index(&value.Origin)
				if !ok {
					return false
				}
				w.Put(index, w.IndexBits)
			}
		}
	}
	{
		if value.Status != FixStatusNone {
			w.Put(10, TableMessageRefBitsHere)
			if value.Status == FixStatusNone {
				w.Put(0, TableMessageRefBitsHere)
			} else {
				id, named := value.Status.TableEnumId()
				if !named {
					return false
				}
				slot := tableMessageNameSlot(id)
				if slot == 0 {
					return false
				}
				w.Put(slot, TableMessageRefBitsHere)
			}
		}
	}
	{
		if value.Kept.Count < 0 {
			return false
		}
		if value.Kept.Count > 0 {
			w.Put(11, TableMessageRefBitsHere)
			if value.Kept.Count < 0 {
				return false
			}
			w.Put(uint64(value.Kept.Count), 32)
			field := &FixTableFields[6]
			if field.Kind == 6 {
				w.Align()
			}
			cursor := tableMapCursor((*tableContainer)(unsafe.Pointer(&value.Kept)), field, w.Numbering.arena)
			defer cursor.Release()
			for i := int32(0); i < value.Kept.Count; i++ {
				p := (*PairRow)(cursor.Next())
				if p == nil {
					return false
				}
				if !PairSaveMessageBody(w, &(*p)) {
					return false
				}
			}
		}
	}
	w.Put(0, TableMessageRefBitsHere)
	return !w.Overflow
}
