func FixesSaveMessageBody(w *TableMessageWriter, value *Fixes) bool {
	{
		if value.Title != 0 {
			w.Put(1, TableMessageRefBitsHere)
			if value.Title == 0 {
				w.Put(0, w.IndexBits)
			} else {
				index, ok := w.Numbering.Index(&value.Title)
				if !ok {
					return false
				}
				w.Put(index, w.IndexBits)
			}
		}
	}
	{
		if value.Text != 0 {
			w.Put(2, TableMessageRefBitsHere)
			if value.Text == 0 {
				w.Put(0, w.IndexBits)
			} else {
				index, ok := w.Numbering.Index(&value.Text)
				if !ok {
					return false
				}
				w.Put(index, w.IndexBits)
			}
		}
	}
	{
		if value.Releases.Count < 0 {
			return false
		}
		if value.Releases.Count > 0 {
			w.Put(12, TableMessageRefBitsHere)
			if value.Releases.Count < 0 {
				return false
			}
			w.Put(uint64(value.Releases.Count), 32)
			field := &FixesTableFields[2]
			if field.Kind == 6 {
				w.Align()
			}
			cursor := tableMapCursor((*tableContainer)(unsafe.Pointer(&value.Releases)), field, w.Numbering.arena)
			defer cursor.Release()
			for i := int32(0); i < value.Releases.Count; i++ {
				p := (*ReleaseRow)(cursor.Next())
				if p == nil {
					return false
				}
				if !ReleaseSaveMessageBody(w, &(*p)) {
					return false
				}
			}
		}
	}
	{
		if value.Items.Count < 0 {
			return false
		}
		if value.Items.Count > 0 {
			w.Put(6, TableMessageRefBitsHere)
			if value.Items.Count < 0 {
				return false
			}
			w.Put(uint64(value.Items.Count), 32)
			field := &FixesTableFields[3]
			if field.Kind == 6 {
				w.Align()
			}
			cursor := tableMapCursor((*tableContainer)(unsafe.Pointer(&value.Items)), field, w.Numbering.arena)
			defer cursor.Release()
			for i := int32(0); i < value.Items.Count; i++ {
				p := (*FixRow)(cursor.Next())
				if p == nil {
					return false
				}
				if !FixSaveMessageBody(w, &(*p)) {
					return false
				}
			}
		}
	}
	w.Put(0, TableMessageRefBitsHere)
	return !w.Overflow
}
func FixesLoadMessageBody(r *TableMessageReader, value *Fixes) bool {
	FixesReset(value)
	for {
		ref, ok := r.Bits.Get(r.Vocabulary.RefBits)
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		entry, ok := r.Vocabulary.Entry(ref)
		if !ok || entry.Id >= 0xfffffffffffffffd {
			r.Report.Malformed = true
			return false
		}
		switch entry.Id {
		case 0xda31296c0c1b6029:
			{
				widened := false
				if entry.Shape.Kind != 17 || entry.Element.Kind != 0 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					index, ok := r.Bits.Get(r.IndexBits)
					if !ok || r.IndexBits <= 0 {
						r.Report.Malformed = true
						return false
					}
					r.Nodes.Resolve(&value.Title, index, 0x704be0d8faaffc58, &r.Report)
				}
				if widened {
					r.Report.Widened++
				}
			}
		case 0xfa04f4ef1995407e:
			{
				widened := false
				if entry.Shape.Kind != 17 || entry.Element.Kind != 0 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					index, ok := r.Bits.Get(r.IndexBits)
					if !ok || r.IndexBits <= 0 {
						r.Report.Malformed = true
						return false
					}
					r.Nodes.Resolve(&value.Text, index, 0x704be0d8faaffc58, &r.Report)
				}
				if widened {
					r.Report.Widened++
				}
			}
		case 0xa539b948612d1f97:
			{
				widened := false
				if entry.Shape.Kind != 14 || entry.Element.Kind != 13 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					count, ok := tableMessageCount(&r.Bits, entry.Shape)
					if !ok {
						r.Report.Malformed = true
						return false
					}
					if entry.Element.Kind == 6 && !r.Bits.Align() {
						r.Report.Malformed = true
						return false
					}
					holder := (*tableContainer)(unsafe.Pointer(&value.Releases))
					if !tableContainerFill(&r.Nodes.Carve, holder, count, 40, 8) {
						r.Report.Malformed = true
						return false
					}
					holder.Count = 0
					element := TableMessageEntry{Shape: entry.Element}
					_ = element
					for i := uint64(0); i < count; i++ {
						p := (*ReleaseRow)(tableContainerFillAt(&r.Nodes.Carve, holder, int32(i), 40))
						if p == nil {
							r.Report.Malformed = true
							return false
						}
						holder.Count++
						if !ReleaseLoadMessageBody(r, &(*p)) {
							return false
						}
					}
				}
				if widened {
					r.Report.Widened++
				}
			}
		case 0x3e7884bf4f412c6f:
			{
				widened := false
				if entry.Shape.Kind != 14 || entry.Element.Kind != 13 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					count, ok := tableMessageCount(&r.Bits, entry.Shape)
					if !ok {
						r.Report.Malformed = true
						return false
					}
					if entry.Element.Kind == 6 && !r.Bits.Align() {
						r.Report.Malformed = true
						return false
					}
					holder := (*tableContainer)(unsafe.Pointer(&value.Items))
					if !tableContainerFill(&r.Nodes.Carve, holder, count, 64, 8) {
						r.Report.Malformed = true
						return false
					}
					holder.Count = 0
					element := TableMessageEntry{Shape: entry.Element}
					_ = element
					for i := uint64(0); i < count; i++ {
						p := (*FixRow)(tableContainerFillAt(&r.Nodes.Carve, holder, int32(i), 64))
						if p == nil {
							r.Report.Malformed = true
							return false
						}
						holder.Count++
						if !FixLoadMessageBody(r, &(*p)) {
							return false
						}
					}
				}
				if widened {
					r.Report.Widened++
				}
			}
		default:
			r.Report.Unknown++
			if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}
func init() {
	PairTableInfo.LoadMessageBodyRetain = func(r TableRetainMessageReader, p unsafe.Pointer) (TableRetainMessageReader, bool) {
		ok := PairLoadMessageBodyRetain(&r, (*Pair)(p))
		return r, ok
	}
	PairTableInfo.SaveMessageBody = func(w *TableMessageWriter, p unsafe.Pointer) bool { return PairSaveMessageBody(w, (*Pair)(p)) }
	PairTableInfo.LoadMessageBody = func(r TableMessageReader, p unsafe.Pointer) (TableMessageReader, bool) {
		ok := PairLoadMessageBody(&r, (*Pair)(p))
		return r, ok
	}
}

